import "aos/dist/aos.css";
import {
    FaWhatsapp,
    FaEnvelope,
    FaMapMarkerAlt,
} from "react-icons/fa";
import AppContext from "../../../Context";
import { useContext } from "react";

function Contact() {
    const WA_NUMBER = "6281213094426";
    const { language } = useContext(AppContext);
    const message =
        language === "id"
            ? `Halo Regarde,\nSaya ingin menghubungi Anda untuk mendapatkan informasi lebih lanjut.`
            : `Hello Regarde,\nI would like to contact you for further information.`;

    const waLink = `https://wa.me/${WA_NUMBER}?text=${encodeURIComponent(message)}`;
    return (
        <div className="pt-28">
            {/* HERO */}
            <section className="pb-20 bg-white">
                <div className="w-11/12 md:w-8/12 mx-auto text-center">
                    <h1
                        data-aos="zoom-in"
                        className="text-5xl font-black text-primary-black-500 mb-4"
                    >
                        {language === "id" ? "Hubungi Kami" : "Contact Us"}
                    </h1>

                    <p
                        data-aos="fade-up"
                        className="text-primary-black-500 max-w-2xl mx-auto"
                    >
                        {language === "id"
                            ? "Hubungi kami untuk mendapatkan informasi lebih lanjut mengenai layanan kami. Tim kami siap mendukung kebutuhan bisnis Anda."
                            : "Get in touch with us for more information about our services. Our team is ready to support your business needs."}
                    </p>
                </div>
            </section>

            {/* CONTACT INFO */}
            <section className="pb-24">
                <div className="w-11/12 md:w-9/12 mx-auto grid grid-cols-1 md:grid-cols-3 gap-8">

                    {/* WHATSAPP */}
                    <div
                        data-aos="fade-up"
                        className="border rounded-xl p-6 text-center hover:shadow-md transition"
                    >
                        <div className="flex justify-center mb-4">
                            <div className="w-14 h-14 rounded-full bg-green-100 flex items-center justify-center">
                                <FaWhatsapp className="text-green-600 text-2xl" />
                            </div>
                        </div>

                        <h3 className="font-semibold text-primary-black-500 mb-2">
                            WhatsApp
                        </h3>

                        <p className="text-sm text-primary-black-500 mb-4">
                            {language === "id"
                                ? "Hubungi kami langsung melalui WhatsApp."
                                : "Contact us directly via WhatsApp."}
                        </p>

                        <a
                            href={waLink}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="inline-block text-sm font-semibold text-green-600 hover:underline"
                        >
                            {language === "id" ? "Chat via WhatsApp" : "Chat via WhatsApp"}
                        </a>
                    </div>

                    {/* EMAIL */}
                    <div
                        data-aos="fade-up"
                        data-aos-delay="100"
                        className="border rounded-xl p-6 text-center hover:shadow-md transition"
                    >
                        <div className="flex justify-center mb-4">
                            <div className="w-14 h-14 rounded-full bg-primary-blue-100 flex items-center justify-center">
                                <FaEnvelope className="text-primary-blue-600 text-2xl" />
                            </div>
                        </div>

                        <h3 className="font-semibold text-primary-black-500 mb-2">
                            Email
                        </h3>

                        <p className="text-sm text-primary-black-500 mb-4">
                            {language === "id"
                                ? "Kirim pertanyaan Anda melalui email."
                                : "Send us your inquiries via email."}
                        </p>

                        <a
                            href="mailto:haloregarde@gmail.com"
                            className="inline-block text-sm font-semibold text-primary-blue-600 hover:underline"
                        >
                            haloregarde@gmail.com
                        </a>
                    </div>

                    {/* LOCATION */}
                    <div
                        data-aos="fade-up"
                        data-aos-delay="200"
                        className="border rounded-xl p-6 text-center hover:shadow-md transition"
                    >
                        <div className="flex justify-center mb-4">
                            <div className="w-14 h-14 rounded-full bg-primary-blue-100 flex items-center justify-center">
                                <FaMapMarkerAlt className="text-primary-blue-600 text-2xl" />
                            </div>
                        </div>

                        <h3 className="font-semibold text-primary-black-500 mb-2">
                            {language === "id" ? "Alamat Kantor" : "Office Address"}
                        </h3>

                        <p className="text-sm text-primary-black-500">
                            {language === "id"
                                ? "Gedung Grand Slipi Tower, Lantai 5 Unit F\nJl. Letjend S. Parman Kav 22-24 RT 001 RW 004\nKelurahan Palmerah, Kecamatan Palmerah\nJakarta Barat – DKI Jakarta"
                                : "Grand Slipi Tower Building, 5th Floor Unit F\nJl. Letjend S. Parman Kav 22-24 RT 001 RW 004\nPalmerah Subdistrict, Palmerah District\nWest Jakarta – Special Capital Region of Jakarta"}
                        </p>
                    </div>

                </div>
            </section>

            {/* MAP */}
            <section className="pb-24">
                <div className="w-11/12 md:w-9/12 mx-auto">
                    <h2
                        data-aos="zoom-in"
                        className="text-center text-4xl font-black text-primary-black-500 mb-12"
                    >
                        {language === 'id' ? 'Lokasi Kami' : 'Our Location'}
                    </h2>
                    <div
                        data-aos="fade-up"
                        className="bg-white rounded-2xl shadow-lg overflow-hidden"
                    >
                        {/* MAP */}
                        <div className="w-full aspect-video">
                            <iframe
                                title="Location"
                                src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3966.476733850875!2d106.79526027499018!3d-6.200664193787056!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e69f730e73b318b%3A0xa627f2fbae3cf0f0!2sREGARDE%20CONSULTANT!5e0!3m2!1sid!2sid!4v1775914193549!5m2!1sid!2sid"
                                className="w-full h-full border-0"
                                allowFullScreen
                                loading="lazy"
                                referrerPolicy="no-referrer-when-downgrade"
                            />
                        </div>

                        {/* ADDRESS */}
                        <div className="px-5 pt-5 flex items-start gap-4">
                            <div className="text-primary-blue-700 text-xl">
                                <FaMapMarkerAlt />
                            </div>
                            <p className="text-primary-black-500 font-semibold leading-relaxed">
                                Regarde Consultant
                            </p>
                        </div>
                        <p className="text-primary-black-500 leading-relaxed text-left p-5">
                            {
                                language === "id"
                                    ? (
                                        <>
                                            Gedung Grand Slipi Tower, Lantai 5 Unit F<br />
                                            Jl. Letjend S. Parman Kav 22-24 RT 001 RW 004<br />
                                            Kelurahan Palmerah, Kecamatan Palmerah<br />
                                            Jakarta Barat – DKI Jakarta 11480
                                        </>
                                    )
                                    : (
                                        <>
                                            Grand Slipi Tower Building, 5th Floor Unit F<br />
                                            Jl. Letjend S. Parman Kav 22-24 RT 001 RW 004<br />
                                            Palmerah Subdistrict, Palmerah District<br />
                                            West Jakarta – Special Capital Region of Jakarta 11480
                                        </>
                                    )
                            }
                        </p>
                    </div>
                </div>
            </section>

            {/* CTA */}
            <section className="pb-24">
                <div className="w-11/12 md:w-8/12 mx-auto text-center">

                    <h2 className="text-3xl font-bold text-primary-black-500 mb-4">
                        {language === "id"
                            ? "Siap Berdiskusi dengan Kami?"
                            : "Ready to Discuss With Us?"}
                    </h2>

                    <p className="text-primary-black-500 mb-8">
                        {language === "id"
                            ? "Tim kami siap membantu kebutuhan bisnis dan konsultasi Anda."
                            : "Our team is ready to assist your business and consultation needs."}
                    </p>

                    <a
                        href={waLink}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="inline-flex items-center gap-3 bg-green-600 text-white px-8 py-4 rounded-full font-semibold hover:bg-green-700 transition"
                    >
                        <FaWhatsapp />
                        {language === "id" ? "Hubungi via WhatsApp" : "Contact via WhatsApp"}
                    </a>

                </div>
            </section>
        </div>
    );
}

export default Contact;